{
  "items": [
    {
      "questionId": "q8",
      "maxMarks": 16,
      "answer": "The working memory model (Baddeley & Hitch, 1974) proposes a multi-component system for short-term processing. It includes the central executive (attentional control), the phonological loop (verbal/acoustic information), the visuospatial sketchpad (visual/spatial information), and the episodic buffer (added in 2000, integrates information). Evaluation includes supporting evidence: KF case study (Shallice & Warrington, 1970) shows intact visual but impaired verbal STM, supporting separate stores; dual-task paradigm studies (e.g., Baddeley et al., 1984) show interference between tasks using same component, supporting distinct stores; word-length effect (Baddeley et al., 1984) supports phonological loop's articulatory rehearsal; brain imaging (e.g., Smith et al., 1995) shows activation in relevant areas. Criticisms: vague role of central executive (little explanation of how it works); model focuses only on STM/short-term processing, not long-term memory; episodic buffer added later, suggesting incomplete original model.",
      "acceptableAlternatives": [
        "Any valid supporting or contradicting evidence accepted: KF (intact visual but impaired verbal STM), dual-task paradigm studies, word-length effect, episodic buffer added in 2000, brain imaging of phonological loop",
        "Criticisms: vague role of central executive, model focuses only on STM/short-term processing"
      ],
      "commonMistakes": [
        "describing components without evaluation",
        "confusing WMM with multi-store model",
        "asserting evidence without naming/summarising the study",
        "unbalanced answer (all support or all criticism)"
      ],
      "marking": "banded",
      "bands": [
        {
          "band": "0-2",
          "description": "Minimal or no understanding of the working memory model. May describe components inaccurately or without evaluation. No evidence cited."
        },
        {
          "band": "3-5",
          "description": "Basic description of the working memory model with some components named. Limited or no evaluation. May mention one piece of evidence but not explained or linked to evaluation."
        },
        {
          "band": "6-8",
          "description": "Adequate description of the working memory model with components explained. Some evaluation attempted, but may be superficial or unbalanced. May cite one or two pieces of evidence with basic explanation."
        },
        {
          "band": "9-11",
          "description": "Good description of the working memory model with clear explanation of components. Balanced evaluation with supporting and/or critical evidence. Evidence is named and summarized, but may lack depth or integration."
        },
        {
          "band": "12-14",
          "description": "Very good description of the working memory model with detailed explanation of components. Strong evaluation with multiple pieces of evidence (supporting and/or critical). Evidence is well-explained and linked to evaluation. May show some analysis of strengths/limitations."
        },
        {
          "band": "15-16",
          "description": "Excellent description of the working memory model with comprehensive explanation of components. Sophisticated evaluation with multiple pieces of evidence (supporting and critical). Evidence is well-explained, integrated, and analyzed. Shows clear understanding of the model's strengths and weaknesses, with balanced discussion."
        }
      ]
    }
  ]
